SELECT DISTINCTROW Имена_станций.NAME AS NAME1, [Рабочий(станции)].YEAR, [Рабочий(станции)].NUST, [Рабочий(станции)].E, [Рабочий(станции)].B, [Рабочий(станции)].UGOL, [Рабочий(станции)].DON, [Рабочий(станции)].PODM, [Рабочий(станции)].PECH, IIf([Рабочий(станции)]![YEAR]=1999,[Разбивка99]![vork],[Рабочий(станции)]![PECH]*[Разбивка-на-перспективу]![vork]) AS Vork, IIf([Рабочий(станции)]![YEAR]=1999,[Разбивка99]![int],[Рабочий(станции)]![PECH]*[Разбивка-на-перспективу]![int]) AS [int], [Рабочий(станции)].ARKT, [Рабочий(станции)].KUZN, IIf([Рабочий(станции)]![YEAR]=1999,0,[Рабочий(станции)]![kuzn]*[Разбивка-на-перспективу]![kuznt]) AS kuznt, IIf([Рабочий(станции)]![YEAR]=1999,0,[Рабочий(станции)]![kuzn]*[Разбивка-на-перспективу]![kuznss]) AS kuznss, IIf([Рабочий(станции)]![YEAR]=1999,0,[Рабочий(станции)]![kuzn]*[Разбивка-на-перспективу]![kuzngd]) AS kuzngd, IIf([Рабочий(станции)]![YEAR]=1999,0,[Рабочий(станции)]![kuzn]*[Разбивка-на-перспективу]![kuznun]) AS kuznun, IIf([Рабочий(станции)]![YEAR]=1999,[Разбивка99]![sver],[Рабочий(станции)]![Ural]*[Разбивка-на-перспективу]![sver]) AS sver, IIf([Рабочий(станции)]![YEAR]=1999,[Разбивка99]![chel],[Рабочий(станции)]![Ural]*[Разбивка-на-перспективу]![chel]) AS chel, IIf([Рабочий(станции)]![YEAR]=1999,[Разбивка99]![kizel],[Рабочий(станции)]![Ural]*[Разбивка-на-перспективу]![kizel]) AS kizel, [Рабочий(станции)].BASHK, [Рабочий(станции)].EKIB AS Выражение1, [Рабочий(станции)].KARAG, [Рабочий(станции)].KAN, [Рабочий(станции)].IRKUT, IIf([Рабочий(станции)]![YEAR]=1999,[Разбивка99]![azey],[Рабочий(станции)]![irkut]*[Разбивка-на-перспективу]![azey]) AS azey, IIf([Рабочий(станции)]![YEAR]=1999,[Разбивка99]![cher],[Рабочий(станции)]![irkut]*[Разбивка-на-перспективу]![cher]) AS cher, [Рабочий(станции)].HAK, [Рабочий(станции)].TUV, [Рабочий(станции)].BUR, IIf([Рабочий(станции)]![YEAR]=1999,[Разбивка99]![gusin],[Рабочий(Доп_угли)]![gusin]) AS gusin, IIf([Рабочий(станции)]![YEAR]=1999,[Разбивка99]![tugn],[Рабочий(Доп_угли)]![tugn]) AS tugn, [Рабочий(станции)].CHIT, [Рабочий(станции)].HER AS Выражение1, [Рабочий(станции)].RAICH AS Выражение2, [Рабочий(станции)].URG, [Рабочий(станции)].PRIM, [Рабочий(станции)].LUCH, [Рабочий(станции)].MAG, [Рабочий(станции)].SAH, [Рабочий(станции)].QOTR, [Рабочий(станции)].SNK, [Рабочий(станции)].EWTP, [Рабочий(станции)].NT, [Рабочий(станции)].OBOR, [Рабочий(станции)].VED, [Рабочий(станции)].OBL, [Рабочий(станции)].DEP, [Рабочий(станции)].OES, [Рабочий(станции)].ER, [Рабочий(станции)].NUMB1120, Имена_станций.ordnumb AS numb1, Имена_областей.NAME AS oblname, IIf([Рабочий(станции)]![YEAR]=1999,[Разбивка99]![nazar],[Рабочий(Доп_угли)]![nazar]) AS nazar, IIf([Рабочий(станции)]![YEAR]=1999,[Разбивка99]![ibor],[Рабочий(Доп_угли)]![ibor]) AS ibor, IIf([Рабочий(станции)]![YEAR]=1999,[Разбивка99]![berez],[Рабочий(Доп_угли)]![berez]) AS berez
FROM Разбивка99, [Разбивка-на-перспективу], (([Рабочий(станции)] INNER JOIN Имена_областей ON [Рабочий(станции)].OBL = Имена_областей.OBL) INNER JOIN Имена_станций ON [Рабочий(станции)].NUMB1120 = Имена_станций.NUMB) LEFT JOIN [Рабочий(доп_угли)] ON ([Рабочий(станции)].NUMB1120 = [Рабочий(доп_угли)].NUMB1120) AND ([Рабочий(станции)].YEAR = [Рабочий(доп_угли)].YEAR)
WHERE ((([Рабочий(станции)].YEAR)>0) AND (([Рабочий(станции)].UGOL)>0));
